.card {
  width: 100%;
  max-width: 30rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  margin: 0 0 0.5rem;
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text);
}

.lede {
  margin: 0 0 1.5rem;
  color: var(--text-muted);
}

.form-field {
  margin-bottom: 1.5rem;
}

.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
}

input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.15rem;
  height: 1.15rem;
  margin: 0.18rem 0 0;
  flex: 0 0 auto;
  background: var(--surface-2);
  border: 1.5px solid var(--border-strong);
  border-radius: 4px;
  cursor: pointer;
  display: grid;
  place-content: center;
  transition: background-color 0.15s, border-color 0.15s;
}

input[type="checkbox"]:hover {
  border-color: var(--accent);
}

input[type="checkbox"]::before {
  content: "";
  width: 0.7rem;
  height: 0.7rem;
  transform: scale(0);
  transition: transform 0.12s ease-in-out;
  background-color: var(--accent-contrast);
  clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%);
}

input[type="checkbox"]:checked {
  background: var(--accent);
  border-color: var(--accent);
}

input[type="checkbox"]:checked::before {
  transform: scale(1);
}

input[type="checkbox"][aria-invalid="true"] {
  border-color: var(--danger);
}

input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

label[for="agree-terms"] {
  cursor: pointer;
  color: var(--text);
  user-select: none;
}

label a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}

label a:hover { color: var(--accent-hover); }

label a:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 2px;
}

.required-mark {
  color: var(--danger);
  margin-left: 0.15rem;
}

.helper-text {
  margin: 0.5rem 0 0 1.775rem;
  font-size: 0.875rem;
  color: var(--text-muted);
}

.error-text {
  margin: 0.5rem 0 0 1.775rem;
  font-size: 0.875rem;
  color: var(--danger);
  font-weight: 500;
}

.submit-btn {
  appearance: none;
  background: var(--accent);
  color: var(--accent-contrast);
  border: 1px solid var(--accent);
  border-radius: 8px;
  padding: 0.625rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s;
}

.submit-btn:hover { background: var(--accent-hover); border-color: var(--accent-hover); }

.submit-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.submit-btn:active { transform: translateY(1px); }

.status {
  margin: 1rem 0 0;
  min-height: 1.25rem;
  font-size: 0.9375rem;
  color: var(--success);
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (forced-colors: active) {
  .card { border: 1px solid CanvasText; }
  input[type="checkbox"] { border: 1.5px solid CanvasText; }
  input[type="checkbox"]:checked { background: Highlight; border-color: Highlight; }
  .submit-btn { border: 1px solid ButtonText; background: ButtonFace; color: ButtonText; }
}
